/**
 * Orange Cloud OAuth 回调中转（最小实现，替代整个 apps/web Next.js 站）
 *
 * Cloudflare OAuth 只接受 https 形式的 redirect_uri，而 App 用的是自定义 scheme
 * orangecloud://oauth/callback。这个 Worker 只做一件事：把 code/state（或 error）
 * 原样 302 回 App。不落盘、不换 token（换 token 与 state 校验都在设备端 + PKCE）。
 *
 * 部署：wrangler deploy    （或直接在 Dashboard 里新建 Worker 粘贴本文件）
 */
// OAuth 应用图标（512×512 PNG，自制：橙色渐变圆角底 + 白云 + YANJIE233）。
// Cloudflare 的 public client 会按 logo_uri 抓图并校验 Content-Type，所以由本 Worker 直接提供。
const LOGO_B64 =
  "";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/logo.png") {
      const bin = Uint8Array.from(atob(LOGO_B64), (c) => c.charCodeAt(0));
      return new Response(bin, {
        headers: { "content-type": "image/png", "cache-control": "public, max-age=86400" },
      });
    }

    if (url.pathname !== "/oauth/callback") {
      return new Response("orange-cloud oauth relay: GET /oauth/callback\n", {
        headers: { "content-type": "text/plain; charset=utf-8" },
      });
    }

    const qs = new URLSearchParams();
    for (const k of ["code", "state", "error", "error_description"]) {
      const v = url.searchParams.get(k);
      if (v) qs.set(k, v);
    }
    if (!qs.has("code") && !qs.has("error")) {
      return new Response("missing code\n", { status: 400 });
    }

    return new Response(null, {
      status: 302,
      headers: {
        location: `orangecloud://oauth/callback?${qs.toString()}`,
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
      },
    });
  },
};
